class Solution { private int[] parent,size;private int find(int value){return parent[value]==value?value:(parent[value]=find(parent[value]));}private void union(int a,int b){a=find(a);b=find(b);if(a==b)return;if(size[a]<size[b]){int swap=a;a=b;b=swap;}parent[b]=a;size[a]+=size[b];}public boolean canTraverseAllPairs(int[] nums){int n=nums.length;if(n==1)return true;for(int value:nums)if(value==1)return false;int maximum=Arrays.stream(nums).max().getAsInt();int[] spf=new int[maximum+1];for(int prime=2;prime<=maximum;prime++)if(spf[prime]==0)for(int multiple=prime;multiple<=maximum;multiple+=prime)if(spf[multiple]==0)spf[multiple]=prime;parent=new int[n];size=new int[n];Arrays.fill(size,1);for(int i=0;i<n;i++)parent[i]=i;Map<Integer,Integer> owner=new HashMap<>();for(int i=0;i<n;i++){int value=nums[i];while(value>1){int prime=spf[value];if(owner.containsKey(prime))union(i,owner.get(prime));else owner.put(prime,i);while(value%prime==0)value/=prime;}}int root=find(0);for(int i=1;i<n;i++)if(find(i)!=root)return false;return true;} }
